pub(crate) fn compare_symbols_ref(
    &self,
    a: &crate::symbol_access::SymbolRef,
    b: &crate::symbol_access::SymbolRef,
) -> std::cmp::Ordering {
    if a == b {
        self.symbols.view(a).expect("selected sort owner");
        return std::cmp::Ordering::Equal;
    }
    let position = |symbol: &crate::symbol_access::SymbolRef| {
        let view = self.symbols.view(symbol).expect("selected sort owner");
        let position = view.declarations().first().map(|&declaration| {
            let mut file = declaration;
            let mut current = Some(declaration);
            while let Some(node) = current {
                if self.nodes.kind(node) == SyntaxKind::SourceFile {
                    file = node;
                    break;
                }
                current = self.nodes.parent(node);
            }
            (file, self.nodes.span(declaration).start)
        });
        (position.is_none(), position)
    };
    let ordering = position(a).cmp(&position(b)).then_with(|| {
        self.symbols
            .view(a)
            .expect("selected sort owner")
            .name()
            .cmp(self.symbols.view(b).expect("selected sort owner").name())
    });
    if ordering != std::cmp::Ordering::Equal {
        return ordering;
    }
    self.symbols
        .view(a)
        .expect("selected sort owner")
        .identity_id()
        .cmp(&self.symbols.view(b).expect("selected sort owner").identity_id())
}

