use tsr_ast::{Node,NodeId,NodeTable,SyntaxKind};
use symbol_access::CheckerSymbols;
mod symbol_access;
#[derive(Clone,Copy,Debug,PartialEq,Eq,Hash)]
pub struct TypeId(u32);
struct Intrinsics { string:TypeId, number:TypeId }
struct Checker<'a,'n> {
 symbols: CheckerSymbols<'a>, nodes:&'n NodeTable,
 alias_evaluation_bindings: Vec<rustc_hash::FxHashMap<symbol_access::SymbolRef,TypeId>>,
 mapped_template_depth:u32, intrinsics:Intrinsics,
}
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub(crate) struct TypeLiteralKey {
    pub(crate) node: tsr_ast::NodeId,
    bindings: Vec<(crate::symbol_access::SymbolRef, TypeId)>,
    mapped_template: bool,
}
impl TypeLiteralKey {
    pub(crate) fn is_unmapped(&self) -> bool {
        self.bindings.is_empty() && !self.mapped_template
    }
}
impl Checker<'_ , '_> {
    pub(crate) fn compare_symbols_ref(
        &self,
        a: &crate::symbol_access::SymbolRef,
        b: &crate::symbol_access::SymbolRef,
    ) -> std::cmp::Ordering {
        if a == b {
            self.symbols.view(a).expect("selected sort owner");
            return std::cmp::Ordering::Equal;
        }
        let position = |symbol: &crate::symbol_access::SymbolRef| {
            let view = self.symbols.view(symbol).expect("selected sort owner");
            let position = view.declarations().first().map(|&declaration| {
                let mut file = declaration;
                let mut current = Some(declaration);
                while let Some(node) = current {
                    if self.nodes.kind(node) == SyntaxKind::SourceFile {
                        file = node;
                        break;
                    }
                    current = self.nodes.parent(node);
                }
                (file, self.nodes.span(declaration).start)
            });
            (position.is_none(), position)
        };
        let ordering = position(a).cmp(&position(b)).then_with(|| {
            self.symbols
                .view(a)
                .expect("selected sort owner")
                .name()
                .cmp(self.symbols.view(b).expect("selected sort owner").name())
        });
        if ordering != std::cmp::Ordering::Equal {
            return ordering;
        }
        self.symbols
            .view(a)
            .expect("selected sort owner")
            .identity_id()
            .cmp(&self.symbols.view(b).expect("selected sort owner").identity_id())
    }
    pub(crate) fn type_literal_key(&self, node: tsr_ast::NodeId) -> TypeLiteralKey {
        let bindings: rustc_hash::FxHashMap<_, _> = self
            .alias_evaluation_bindings
            .iter()
            .flat_map(|frame| frame.iter().map(|(symbol, &ty)| (symbol.clone(), ty)))
            .collect();
        let mut bindings: Vec<_> = bindings.into_iter().collect();
        bindings.sort_unstable_by(|(left, _), (right, _)| self.compare_symbols_ref(left, right));
        TypeLiteralKey { node, bindings, mapped_template: self.mapped_template_depth > 0 }
    }
}
#[cfg(test)]
mod selected_binding_key_tests {
    use super::*;
    use crate::symbol_access::SymbolRef;

    fn inspect_keys(test: impl FnOnce(&mut Checker<'_, '_>, NodeId, SymbolRef, SymbolRef)) {
        let arena = tsr_core::Arena::new();
        let text = "type Box<T, U> = { first:T; second:U };";
        let parsed = tsr_parser::parse(&arena, text);
        assert!(parsed.diagnostics.is_empty());
        let bound = tsr_binder::bind(
            &arena,
            parsed.source_file,
            &parsed.nodes,
            tsr_binder::FileInfo { name: "binding-keys.ts", text },
        );
        let first = bound.symbols().iter().find(|(_, symbol)| symbol.name == "T").unwrap().0;
        let second = bound.symbols().iter().find(|(_, symbol)| symbol.name == "U").unwrap().0;
        let root = Node::SourceFile(parsed.source_file).node_id().unwrap();
        let mut checker = Checker { symbols: CheckerSymbols::new(bound.symbols(), TypeId(0)), nodes: &parsed.nodes, alias_evaluation_bindings: Vec::new(), mapped_template_depth: 0, intrinsics: Intrinsics { string:TypeId(1), number:TypeId(2) } };
        let first = checker.symbols.bound(first).unwrap();
        let second = checker.symbols.bound(second).unwrap();
        test(&mut checker, root, first, second);
    }

    #[test]
    fn binding_keys_preserve_private_parameter_identity() {
        inspect_keys(|checker, root, original, _| {
            let copy = checker.symbols.clone_module_symbol(&original).unwrap();
            let twin = checker.symbols.clone_module_symbol(&original).unwrap();
            let argument = checker.intrinsics.string;
            let mut keys = rustc_hash::FxHashSet::default();
            for owner in [original, copy, twin] {
                checker.alias_evaluation_bindings.push([(owner, argument)].into_iter().collect());
                assert!(keys.insert(checker.type_literal_key(root)));
                checker.alias_evaluation_bindings.pop();
            }
            assert_eq!(keys.len(), 3);
        });
    }

    #[test]
    fn binding_keys_normalize_order_and_keep_inner_shadowing() {
        inspect_keys(|checker, root, first, second| {
            let outer = checker.intrinsics.string;
            let inner = checker.intrinsics.number;
            checker
                .alias_evaluation_bindings
                .push([(first.clone(), outer), (second.clone(), inner)].into_iter().collect());
            let forward = checker.type_literal_key(root);
            checker.alias_evaluation_bindings.pop();
            checker
                .alias_evaluation_bindings
                .push([(second, inner), (first.clone(), outer)].into_iter().collect());
            assert_eq!(checker.type_literal_key(root), forward);
            checker.alias_evaluation_bindings.push([(first.clone(), inner)].into_iter().collect());
            let shadowed = checker.type_literal_key(root);
            assert_ne!(shadowed, forward);
            assert_eq!(
                shadowed.bindings.iter().find(|(owner, _)| owner == &first).unwrap().1,
                inner
            );
            checker.alias_evaluation_bindings.pop();
            assert_eq!(checker.type_literal_key(root), forward);
            checker.alias_evaluation_bindings.pop();
            assert!(checker.type_literal_key(root).is_unmapped());
            checker.mapped_template_depth = 1;
            assert!(!checker.type_literal_key(root).is_unmapped());
        });
    }

    #[test]
    fn binding_keys_keep_distinct_copies_when_frames_are_reordered() {
        inspect_keys(|checker, root, original, _| {
            let copy = checker.symbols.clone_module_symbol(&original).unwrap();
            let twin = checker.symbols.clone_module_symbol(&original).unwrap();
            let argument = checker.intrinsics.string;
            checker
                .alias_evaluation_bindings
                .push([(copy.clone(), argument)].into_iter().collect());
            checker
                .alias_evaluation_bindings
                .push([(twin.clone(), argument)].into_iter().collect());
            let forward = checker.type_literal_key(root);
            assert_eq!(forward.bindings.len(), 2);
            checker.alias_evaluation_bindings.clear();
            checker.alias_evaluation_bindings.push([(twin, argument)].into_iter().collect());
            checker.alias_evaluation_bindings.push([(copy, argument)].into_iter().collect());
            assert_eq!(checker.type_literal_key(root), forward);
        });
    }
}

